    c('T105-fine', 'TRAPS; PLAN 4', 'say(undef or 1); say(undef xor 1); say defined(1 ? undef : 2) ? "d" : "u";', out='1\n1\nu\n'),
    c('P4-compare', 'PLAN 4; T39', 'say 9007199254740993 == 2**53; say "[", 9007199254740993 == 9007199254740992, "]"; say 9007199254740993 == 9007199254740992.0; say 9007199254740993 <=> 9007199254740992.0; say 1 <=> 2; say 2 <=> 1; say 3 <=> 3.0; say "1.0" == 1; say 9223372036854775807 == 9223372036854775808.0;', out='1\n[]\n1\n0\n-1\n1\n0\n1\n1\n'),
    c('P4-strings', 'PLAN 4', 'say 10 lt 9; say "[", 10 < 9, "]"; say "[", "1.0" eq 1, "]"; say 1.0 eq 1; say "[", 0.1 + 0.2 == 0.3, "]"; say 0.1 + 0.2 eq 0.3; say "a" cmp "b"; say "2" cmp "10"; say "\\x{e9}" lt "\\x{100}"; say "\\x{10000}" gt "\\x{ffff}"; say "a\\0" gt "a";', out='1\n[]\n[]\n1\n[]\n1\n-1\n1\n1\n1\n1\n'),
    c('T33-chains', 'TRAPS; PLAN 4', 'say 1 < 5 < 3 ? "y" : "n"; say "[", 1 != 1 == 0, "]"; say 1 < 2 == 1; say 1 == 2 < 3; say 1 < 2 lt 3;', out='n\n[]\n1\n1\n1\n'),
    c('T51-more', 'TRAPS; PLAN 4', 'say 1 == 2 <=> 3;', compiles=False, err='syntax error'),
    c('P4-truth', 'PLAN 4', 'say "0.0" || "f"; say "00" || "f"; say " " || "f"; say 0.0 || "f"; say -0.0 || "f"; say "0" || "f"; say "" || "f"; say 5e-324 || "f"; say "[", 0 && 1, "]"; say 2 || 3; say 1 && "y"; say 0 // 5; say "[", "" // 5, "]";', out='0.0\n00\n \nf\nf\nf\nf\n4.94065645841247e-324\n[0]\n2\ny\n0\n[]\n'),
    c('P4-short', 'PLAN 4', 'say 1 || 1/0; say 0 && 1/0; say 1 // 1/0; say 1 ? 2 : 1/0;', out='1\n0\n1\n2\n'),
    c('P4-ternary', 'PLAN 4', 'say 0 ? 2 : 3 ? 4 : 5; say 1 ? 0 ? "a" : "b" : "c"; say 0 ? 2 : 3 + 1; say 1 || 2 ? 3 : 4; say 0 ? 1 : 2 || 3;', out='4\nb\n4\n3\n2\n'),
    c('P4-precedence', 'PLAN 4', 'say "[", !2 ** 2, "]"; say !1 + 1; say !1 . "a"; say 1 && 0 || 2; say 1 || 0 && 2; say 0 || 0 // 5; say length "ab" == 2; say defined 1 == 1; say 1 + 2 == 3; say "a" . "b" eq "ab"; say 2 x 3 == 222;', out='[]\n1\na\n2\n1\n0\n1\n1\n1\n1\n1\n'),
    c('T106', 'TRAPS; PLAN 4', 'say 0 or 2;', out='0\n', err='Useless use of a constant'),
    c('T106-and', 'TRAPS; PLAN 4', 'say true and false;', out='1\n'),
    c('T106-brackets', 'TRAPS; PLAN 4', 'say(0 or 2); say(1 and 2); say "[", (1 xor 1), "]"; say(0 xor 5); say(1 or 0 and 0); say "[", (0 or 1 xor 1), "]";', out='2\n2\n[]\n1\n1\n[]\n'),
    c('T107', 'TRAPS; PLAN 4', 'say "[", (not 0 || 1), "]"; say(not(0) || 1); say(not (0) + 1); say((not 1) . "a"); say(1 + not 0); say(1 && not 0);', out='[]\n1\n2\na\n2\n1\n'),
    c('T104', 'TRAPS; PLAN 4', 'say scalar(() = (0 || ("a") x 3)); say scalar(() = (1 && ("a") x 3)); say scalar(() = (undef // ("a") x 3)); say scalar(() = (1 ? ("a") x 3 : "b")); say scalar(() = (("a") x 3 || 0)); say scalar(() = (1 xor ("a") x 3));', out='3\n3\n3\n3\n1\n1\n'),
    c('P4-spelling', 'PLAN 4', 'say 1<2; say 1 <=>2; say "a"lt"b"; say 1?2:3; say true .5; say true -1; say true x3;', out='1\n-1\n1\n2\n15\n0\n111\n'),
    c('P4-spelling-refused', 'PLAN 4', 'say 1 lt2;', compiles=False, err='syntax error'),
    c('P4-defined-ambiguous', 'PLAN 4; T94', 'say defined - 1;', out='1\n', err='Use of "defined" without parentheses is ambiguous'),
    c('P4-newer', 'PLAN 4; SURFACE', 'say 1 ^^ 0; say true(); say "[", (defined), "]";', out='1\n1\n[]\n'),
    c('T109', 'TRAPS; D51', 'say substr("abcdef", not 0, 1); say substr("abcdef", (not 0), 1); say substr("abcdef", not(0), 1);', out='abcdef\nb\nb\n'),
    c('T109-or', 'TRAPS; D51', 'say index("abcabc", "c", 0 or 3);', out='', err='Not enough arguments for index', compiles=False),
    c('L4-examples', 'LANGUAGE', 'say 1 < 2; say "[", 1 > 2, "]"; say true + 1; say "[" . (1 > 2) . "]"; say 2 <=> 10; say "2" == 2.0; say "apple" lt "banana"; say "2" cmp "10"; say 0 || "default"; say 5 && 7; say 0 && 7; say 0 ? "a" : 1 ? "b" : "c"; say defined undef ? "yes" : "no"; say undef // "fallback"; say 0 // 5; say 0 || 5;', out='1\n[]\n2\n[]\n-1\n1\n1\n1\ndefault\n7\n0\nb\nno\nfallback\n0\n5\n'),
    # ---- step 5's proposal (PLAN.md) and T110 to T114
    c('T110', 'TRAPS; PLAN 5; D14', 'my $x = 3; say $x + ($x = 5); $x = 3; say(($x || 0) + ($x = 5)); $x = 3; say((1 ? $x : 0) + ($x = 5)); $x = 3; say((++$x) + ($x = 5)); $x = 3; say(($x += 1) + ($x = 5)); $x = 3; say(+$x + ($x = 5));', out='10\n10\n10\n10\n10\n10\n'),
    c('T110-values', 'TRAPS; PLAN 5', 'my $x = 3; say(($x++) + ($x = 5)); $x = 3; say(-$x + ($x = 5)); $x = 3; say(($x == 3) + ($x = 5)); $x = 1; say $x . $x++; $x = 1; say ++$x + $x++;', out='8\n2\n6\n21\n5\n'),
    c('T110-lvalue', 'PLAN 5', 'my $x = 2; ($x = 5) = 7; say $x; ($x += 1) *= 3; say $x; (1 ? $x : $x) = 8; say $x;', out='7\n24\n8\n'),
    c('T111', 'TRAPS; PLAN 5; T26', 'my $x = 5; say "before"; say $x -1;', out='before\n', err="Can't use string", exit='nonzero'),
    c('T111-brackets', 'TRAPS; PLAN 5', 'my $x = 5; say "before"; say($x -1);', out='before\n', err="Can't use string", exit='nonzero'),
    c('T111-plus', 'TRAPS; PLAN 5', 'my $x = 5; my $y = 2; say "before"; say $x +$y;', out='before\n', err="Can't use string", exit='nonzero'),
    c('T111-point', 'TRAPS; PLAN 5', 'my $x = 5; say "before"; print $x .5;', out='before\n', err="Can't use string", exit='nonzero'),
    c('T111-step', 'TRAPS; PLAN 5', 'my $x = 5; say $x ++;', compiles=False, err='syntax error'),
    c('T111-inner', 'TRAPS; PLAN 5', 'my $x = 5; say(($x -1));', compiles=False, err='syntax error'),
    c('T111-less', 'TRAPS; PLAN 5', 'my $x = 5; say $x <true;', compiles=False, err='Unterminated <> operator'),
    c('T111-fine', 'TRAPS; PLAN 5', 'my $x = 5; say $x - 1; say $x-1; say +$x -1; say "" . $x -1; say $x ?1 : 2; say $x **2; say $x -= 1; say -$x -1; say length $x -1; my $y = $x -1; say $y; say $x x 2; say $x lt 6;', out='4\n4\n4\n4\n1\n25\n4\n-5\n1\n3\n44\n1\n'),
    c('T112', 'TRAPS; PLAN 5', 'my $x = 5; if ($x = 6) { say $x }', out='6\n', err='Found = in conditional'),
    c('T112-places', 'TRAPS; PLAN 5', 'my $x = 5; say(($x = 6) ? "t" : "f"); say(($x = 6) && "t"); say(($x = 6) || "t"); say(($x = 6) // "t"); say "t" if $x = 6; if (1 && ($x = 6)) { say $x } if (my $y = 6) { say $y } if ($x = true) { say $x }', out='t\nt\n6\n6\nt\n6\n6\n1\n', err='(?s)(Found = in conditional.*){8}'),
    c('T112-quiet', 'TRAPS; PLAN 5', 'my $x = 5; my $y = 6; if ($x = $y) { say $x } if ($x += 1) { say $x } if ($x = undef) { say 1 } else { say "e" } say "[", !($x = 6), "]"; say "[", (($x = 6) xor 1), "]"; say(1 && ($x = 6)); if (0) { } elsif ($x = 7) { say $x }', out='6\n7\ne\n[]\n[]\n6\n7\n'),
    c('T113-strings', 'TRAPS; PLAN 5', 'my $s = "aa"; $s++; say $s; $s = "Az"; $s++; say $s; $s = "zz"; $s++; say $s; $s = "a9"; $s++; say $s; $s = ""; $s++; say $s; $s = "ab"; $s--; say $s; $s = "12"; $s++; say $s; $s = "1.5"; $s++; say $s;', out='ab\nBa\naaa\nb0\n1\n-1\n13\n2.5\n'),
    c('T113-two', 'TRAPS; PLAN 5', 'my $s = "009"; $s++; say $s; my $u = "009"; my $t = $u + 0; $u++; say $u; my $d = "010"; $d--; say $d;', out='010\n10\n9\n'),
    c('T113-lost', 'TRAPS; PLAN 5', 'my $x = 1e16; $x--; say $x;', out='1e+16\n', err='Lost precision when decrementing'),
    c('T113-lost-up', 'TRAPS; PLAN 5', 'my $x = 9007199254740992.0; $x++; say $x;', out='9.00719925474099e+15\n', err='Lost precision when incrementing'),
    c('T113-ends', 'TRAPS; PLAN 5', 'my $x = 9223372036854775807; $x++; say $x; my $y = 1e15; $y++; say $y; my $z = 1.5; $z++; say $z; $z--; $z--; say $z; my $t = true; $t++; say $t;', out='9223372036854775808\n1000000000000001\n2.5\n0.5\n2\n'),
    c('T43-more', 'TRAPS; PLAN 5', 'my $x; say ++$x; my $y; say --$y; my $z; my $old = $z++; say $old; my $w; $old = $w--; say defined $old ? "defined" : "undef";', out='1\n-1\n0\nundef\n'),
    c('P5-assigning', 'PLAN 5; SURFACE', 'my $a1; $a1 += 1; say $a1; my $b1; $b1 -= 1; say $b1; my $c1; $c1 .= "a"; say $c1; my $d1; $d1 ||= 5; say $d1; my $e1; $e1 //= 6; say $e1; my $f1; $f1 &&= 7; say defined $f1 ? "d" : "u";', out='1\n-1\na\n5\n6\nu\n'),
    c('P5-assigning-warns', 'PLAN 5; SURFACE', 'my $x; $x *= 2; my $y; $y /= 2; my $z; $z **= 2; my $w; $w %= 2; my $v; $v x= 2; say "done";', out='done\n', err='(?s)(Use of uninitialized value.*){5}'),
    c('T114-masks', 'TRAPS; PLAN 5', 'my $x = 1; my $x = 2; say $x;', out='2\n', err='"my" variable \\$x masks earlier declaration in same scope'),
    c('T114-undeclared', 'TRAPS; PLAN 5', 'my $y = $y; say 1;', compiles=False, err='Global symbol "\\$y" requires explicit package name'),
    c('T114-scopes', 'TRAPS; PLAN 5; T58', 'my $x = 5; { my $x = $x + 1; say $x } say $x; if ((my $n = 5) > 3) { say $n } else { say -$n }', out='6\n5\n5\n'),
    c('T114-void', 'TRAPS; PLAN 5', 'my $x = 3; $x; $x + 1; $x == 3; say "done";', out='done\n', err='(?s)Useless use of private variable.*Useless use of addition.*Useless use of numeric eq'),
    c('T114-spellings', 'TRAPS; PLAN 5', 'my $x = 1; say $ x; ($x) = 4; say $x; my $a = 1; my $b = 2; say $a + $b; our $o = 1; say $o;', out='1\n4\n3\n1\n'),
    c('T114-braces', 'TRAPS; PLAN 5', 'my $x = 1; say ${x};', out='1\n', err='Ambiguous use of \\$\\{x\\} resolved to \\$x'),
    c('T30-again', 'TRAPS; PLAN 5', 'my $x = 10 if 1; say $x; my $y = 0; unless ($y) { say "a" } elsif (1) { say "b" } unless (1) { say "c" } else { say "d" }', out='10\na\nd\n'),
    c('T112-not', 'TRAPS; D53', 'my $x = 5; my $y = 1; if (!($x = 6)) { say 1 } if (not $x = 6) { say 1 } if (+($x = 6)) { say 2 } say(!($x = 6) && 1); if (!(($x = 6) && $y)) { say 1 }', out='2\n\n', err='(?s)(Found = in conditional.*){5}'),
    c('T112-not-quiet', 'TRAPS; D53', 'my $x = 5; my $y = 1; say "[", !($x = 6), "]"; $y = !($x = 6); if (!($y && ($x = 6))) { say 1 } if (-($x = 6)) { say 2 } if (!!($x = 6)) { say 3 }', out='[]\n1\n2\n3\n'),
    c('T112-joined', 'TRAPS; D56', 'my $x; my $y; $x = 1 and $y = 2; say $x, $y;', out='12\n', err='Found = in conditional'),
    c('T116', 'TRAPS; D56', '{ }', out='', err='Useless use of anonymous hash \\(\\{\\}\\) in void context'),
    c('T116-nested', 'TRAPS; D56', 'say 1; { { } } say 2;', out='1\n2\n', err='Useless use of anonymous hash'),
    c('T116-syntax', 'TRAPS; D56', 'say 1; { } say 2;', compiles=False, err='syntax error'),
    c('T116-if', 'TRAPS; D56', 'if (1) { } else { } say 1;', out='1\n'),
    c('T117', 'TRAPS; D57', 'my $x = 3; say $x . "a" . ($x = 5);', out='5a5\n'),
    c('T117-folded', 'TRAPS; D57', 'my $x = 3; say((1 ? $x . "" : 0) . ($x = 5)); $x = 3; say(($x . "a") . ($x = 5));', out='55\n5a5\n'),
    c('T117-values', 'TRAPS; D57', 'my $x = 3; my $y = $x . "a"; say $y . ($x = 5); $x = 3; say(($x . "a") x 1 . ($x = 5)); $x = 3; say(($x + 0) . "a" . ($x = 5)); $x = 3; say(length($x . "abc") . ($x = "wxyz"));', out='3a5\n3a5\n3a5\n4wxyz\n'),
    c('T117-earlier', 'TRAPS; D57', 'my $x = 3; say(($x = 5) . $x); say $x++ . $x; say $x . ++$x; $x = 3; $x .= "a" . $x++; say $x;', out='55\n56\n77\n4a3\n'),
    c('T118', 'TRAPS; D56', 'my $u;\nsay 1\n  if\n  $u + 1;\nif (0) { }\nelsif\n  (\n  $u * 2) { }', out='1\n', err='(?s)in addition \\(\\+\\) at \\S+ line 3\\..*in multiplication \\(\\*\\) at \\S+ line 7\\.'),
    c('D56-undef-modifier', 'DECISIONS D56', 'my $x = 1; my $y = 1; $x = undef if $y; say defined $x ? "def" : "undef";', out='undef\n'),
    # ---- by the review of step 5
    c('T112-folded', 'TRAPS; D53', 'my $x = 1; my $y = 3; if ($x = 0 && $y) { say "a" } say $x; say "b" if $x = "p" . (1 || $y); if (my $w = (1 || $y)) { say $w }', out='0\nb\n1\n', err='(?s)(Found = in conditional.*){3}'),
    c('T112-not-folded', 'TRAPS; D53', 'my $x = 1; my $y = 3; if ($x = $y && 0) { say "a" } if ($x = $y || 5) { say $x } if ($x = $y ? 1 : 0) { say $x }', out='3\n1\n'),
    c('T125', 'TRAPS; D56', 'my $x = 5; say substr($x -1, 0);', compiles=False, err='Missing comma after first argument to substr function'),
    c('T125-index', 'TRAPS; D56', 'my $x = "abc"; say index($x .5, "c");', compiles=False, err='Missing comma after first argument to index function'),
    c('T125-fine', 'TRAPS; D56', 'my $n = 5; my $m = 2; say substr("abcdef", $n -1); say index("abcabc", "c", $m +1); say substr($n - 1, 0); say length $n -1;', out='ef\n5\n4\n1\n'),
    c('T126', 'TRAPS; D55', 'my $' + 'v' + 'a' * 251 + ' = 1;', compiles=False, err='Identifier too long'),
    c('T126-fine', 'TRAPS; D55', 'my $' + 'v' + 'a' * 250 + ' = 251; say $' + 'v' + 'a' * 250 + ';', out='251\n'),
    c('T127', 'TRAPS; D56', 'my $y = 2; my $x =- $y; say $x; $x =+ $y; say $x;', out='-2\n2\n', err='(?s)Reversed -= operator.*Reversed \\+= operator'),
    c('T127-quiet', 'TRAPS; D56', 'my $y = 2; my $x =-$y; $x = - $y; $x +=- 1; $x -=+ 1; say $x; say $x ==- 4;', out='-4\n1\n'),
    c('T128', 'TRAPS; T76', 'my $x = 1;\nsay ("a")\nif $x;\nprint ("b" .\n"c") unless !$x;\nsay "";', out='a\nbc\n', err='(?s)say \\(...\\) interpreted as function.*print \\(...\\) interpreted as function'),
    c('T128-quiet', 'TRAPS; T76', 'my $x = 1; say ("a") if $x; say ("b")   unless !$x;', out='a\nb\n'),
    c('T129', 'TRAPS; D57', 'my $t = "t"; my $u = "u"; my $x = "a"; my $z = "1"; $t .= ($u = $x . $z); say $t; say $u;', out='ta1\nu\n'),
    c('T129-shapes', 'TRAPS; D57', 'my $t = "t"; my $u = "u"; my $x = "a"; $t .= $u = $x . 1; say $u; $t .= +($u = "k" . $x); say $u; $t .= (1 ? ($u = $x . "-") : 0); say $u; $t .= (my $w = $x . $x); say defined $w ? "def" : "undef";', out='u\nu\nu\ndef\n'),
    c('T129-fine', 'TRAPS; D57', 'my $t = "t"; my $u = "u"; my $x = "a"; my $z = "1"; $t .= ($u .= $x); say $u; $t = $t . ($u = $x . $z); say $u; $t .= ($u = $z . $x) . "b"; say $u; $t .= ($u = $x x 2); say $u; $t .= ($u = $x . $z . $x); say $u; say $t;', out='ua\na1\n1a\naa\na1a\ntuaa11abaaa1a\n'),
    c('T130', 'TRAPS; D52', 'my $x = 9007199254740994.0; $x++; say $x;', out='9.007199254741e+15\n', err='Lost precision when incrementing 9007199254740994.000000 by 1'),
    c('T130-edges', 'TRAPS; D52', 'my $p = 9007199254740992.0; my $x = $p; $x--; $x = -$p; $x++; $x = $p; $x++; $x = -$p; $x--; $x = $p + 2; $x--; $x = -$p - 2; $x++; say "done";', out='done\n', err='(?s)^(Lost precision when (in|de)crementing \\S+ by 1 at \\S+ line \\d+\\.\\n){4}$'),
    # ---- building step 6
    c('T131', 'TRAPS; t/README', 'my $i = 9223372036854775806; my $k = 0; while ($k++ < 3) { $i++; } say $i; $i = "zero"; $k = 0; while ($i == 0 && $k++ < 2) { print $k; } say "";', out='9223372036854775809\n12\n', err='(?s)^(Argument "zero" isn\'t numeric in numeric eq \\(==\\) at \\S+ line 2\\.\\n)$'),
    # ---- proposing step 6
    c('T32-next', 'TRAPS; PLAN 6', 'my $i = 0; while ($i++ < 3) { { next; } print $i; } say ""; $i = 0; while ($i++ < 3) { { { last; } print "a"; } print $i; } say ""; { last; say "no"; } say "after";', out='123\na1a2a3\nafter\n'),
    c('T32-if', 'TRAPS; PLAN 6', 'my $i = 0; while ($i++ < 3) { if ($i == 2) { next; } print $i; } say ""; $i = 0; W: while ($i++ < 3) { { last W; } say "no"; } say $i;', out='13\n1\n'),
    c('T64-last', 'TRAPS; PLAN 6', 'my $i = 0; while ($i++ < 3) { do { last; } while (0); say "in ", $i; } say "out";', out='out\n'),
    c('T64-dies', 'TRAPS; PLAN 6', 'my $i = 0; do { last; } while ($i++ < 3); say "out";', out='', err='Can\'t "last" outside a loop block', exit=255),
    c('T119', 'TRAPS; PLAN 6', 'my $i = 0; while ((my $x .= "a") && $i++ < 3) { print $x, " "; } say "";', out='a a a \n'),
    c('T119-body', 'TRAPS; PLAN 6', 'my $i = 0; while ($i < 4) { $i++; next if $i == 2; my $x; $x++; print $x; } say "";', out='111\n'),
    c('T119-scope', 'TRAPS; PLAN 6', 'my $i = 0; while ((my $d = $i++) < 3) { my $d = "s"; print $d; } say ""; for (my $k = 0; $k < 3; $k++) { my $k = 9; print $k; } say "";', out='sss\n999\n'),
    c('T119-gone', 'TRAPS; PLAN 6', 'for (my $i = 0; $i < 3; $i++) { } say $i;', compiles=False, err='Global symbol "\\$i" requires explicit package name'),
    c('T119-modifier', 'TRAPS; PLAN 6', 'my $i = 0; my $x = 5 while $i++ < 3; say $x;', out='\n', err='Use of uninitialized value \\$x in say'),
    c('T120', 'TRAPS; PLAN 6', 'my $i = 0; while ($i++ < 3) { last + 1; } say $i;', out='', err='Label not found for "last 1"', exit=255),
    c('T120-dynamic', 'TRAPS; PLAN 6', 'my $i = 0; my $l = "L"; L: while ($i++ < 3) { last $l; } say $i; $i = 0; L: while ($i++ < 3) { last "L"; } say $i;', out='1\n1\n'),
    c('T120-expression', 'TRAPS; PLAN 6', 'my $i = 0; while ($i++ < 3) { $i == 2 and last; print $i; } say ""; $i = 0; while ($i++ < 3) { my $x = last; } say $i; $i = 0; while ($i++ < 3) { say last; } say $i; $i = 0; while ($i++ < 3) { last while 1; } say $i; $i = 0; while ($i++ < 3) { last() if $i == 2; } say $i;', out='1\n1\n1\n1\n2\n'),
    c('T121', 'TRAPS; PLAN 6', 'my $i = 0; L: say 1; M: if ($i == 0) { say 2; } outer: while ($i++ < 3) { last outer; } say $i; N : while (1) { last N; }', out='1\n2\n1\n'),
