    c('T140-last', 'TRAPS; PLAN 8', 'sub a1() { my $x = 5; } say a1(); sub a2() { my $x; } my $v = a2(); say defined($v) ? "d" : "u"; my $i = 3; sub a3() { $i++ } say a3(); say $i; sub a4($x) { $x * 2 } say a4(4); sub a5() { 42; } say a5();', out='5\nu\n3\n4\n8\n42\n'),
    c('T140-useless', 'TRAPS; PLAN 8', 'sub f($x) { $x * 2; return 1 } say f(2);', out='1\n', err='Useless use of multiplication \\(\\*\\) in void context'),
    c('T140-quiet', 'TRAPS; PLAN 8', 'sub f($x) { if ($x) { $x * 2 } } f(2); sub h() { "s" } h(); sub k($x) { $x } k(1); say "ok";', out='ok\n'),
    c('T141', 'TRAPS; PLAN 8', 'sub f($x, $x) { return $x } say f(1, 2);', out='2\n', err='"my" variable \\$x masks earlier declaration in same scope'),
    c('T141-my', 'TRAPS; PLAN 8', 'sub f($x) { my $x = 5; return $x } say f(1);', out='5\n', err='"my" variable \\$x masks earlier declaration in same scope'),
    c('T141-file', 'TRAPS; PLAN 8', 'my $x = 1; sub f($x) { $x++; return $x } say f(5); say $x; sub g($p) { $p = $p * 2; $p++; return $p } my $v = 4; say g($v); say $v;', out='6\n1\n9\n4\n'),
    c('T142-99', 'TRAPS; PLAN 8', 'sub d($n) { return $n == 0 ? 0 : 1 + d($n - 1) } say d(98);', out='98\n'),
    c('T142-100', 'TRAPS; PLAN 8', 'sub d($n) { return $n == 0 ? 0 : 1 + d($n - 1) } say d(99);', out='99\n', err='^Deep recursion on subroutine "main::d" at \\S+ line 2\\.\\n$'),
    c('T142-mutual', 'TRAPS; PLAN 8', 'sub ev($n) { return $n == 0 ? 1 : od($n - 1) } sub od($n) { return $n == 0 ? 0 : ev($n - 1) } say ev(150);', out='1\n'),
    c('T142-mutual-deep', 'TRAPS; PLAN 8', 'sub ev($n) { return $n == 0 ? 1 : od($n - 1) } sub od($n) { return $n == 0 ? 0 : ev($n - 1) } say ev(250);', out='1\n', err='(?s)Deep recursion on subroutine "main::ev".*Deep recursion on subroutine "main::od"'),
    c('T142-pragma', 'TRAPS; PLAN 8', "no warnings 'recursion'; sub d($n) { return $n == 0 ? 0 : 1 + d($n - 1) } say d(5000);", out='5000\n'),
    c('T142-scope', 'TRAPS; PLAN 8', 'sub d($n) { return $n == 0 ? 0 : 1 + d($n - 1) } { no warnings "recursion"; say d(200); } no warnings "recursion"; say d(200);', out='200\n200\n', err='(?s)(Deep recursion on subroutine "main::d".*){2}'),
    c('T142-inside', 'TRAPS; PLAN 8', 'sub d($n) { no warnings "recursion"; return $n == 0 ? 0 : 1 + d($n - 1) } say d(200);', out='200\n'),
    c('PLAN8-arity', 'PLAN 8', 'sub f($x, $y) { return $x } say "a";\nsay f(1);', out='a\n', err="Too few arguments for subroutine 'main::f' \\(got 1; expected 2\\) at \\S+ line 3\\.", exit=255),
    c('PLAN8-arity-many', 'PLAN 8', 'sub f($x, $y = 2) { return $x + $y } say f(1); say f(1, 5);\nsay f(1,\n2, 3);', out='3\n6\n', err="Too many arguments for subroutine 'main::f' \\(got 3; expected at most 2\\) at \\S+ line 3\\.", exit=255),
    c('PLAN8-arity-order', 'PLAN 8', 'sub f($x) { return $x } sub loud() { say "loud"; return 1 } say f(loud(), loud());', out='loud\nloud\n', err='Too many arguments', exit=255),
    c('PLAN8-defaults', 'PLAN 8', 'sub f($x //= 7, $y ||= 8) { return "$x,$y" } say f(); say f(undef, 0); say f(0, ""); say f(1, 2); sub g($x, $y = $x * 2) { return $y } say g(4); say g(4, 1); my $n = 0; sub h($x = $n++) { return $x } say h(); say h(9); say h(); say $n;', out='7,8\n7,8\n0,8\n1,2\n8\n1\n0\n9\n1\n2\n'),
    c('PLAN8-placeholders', 'PLAN 8', 'sub f($, $y) { return $y } say f(1, 2); sub g($=) { return "g" } say g(); say g(1); sub h($ = 5, $z = 6) { return $z } say h(); say h(1,2); my $n = 0; sub k($ = $n++) { return "k" } k(); k(1); k(); say $n; sub m2($//=, $||=) { return "m" } say m2();', out='2\ng\ng\n6\n2\n2\nm\n'),
    c('PLAN8-mandatory', 'PLAN 8', 'sub f($x = 1, $y) { return $x }', compiles=False, err='Mandatory parameter follows optional parameter'),
    c('PLAN8-default-call', 'PLAN 8', 'sub f($n, $acc = one()) { return $n == 0 ? $acc : f($n - 1, $acc * 2) } sub one() { return 1 } say f(10); sub g($x, $y = ($x = 9)) { return "$x $y" } say g(1); say g(1, 2);', out='1024\n9 9\n1 2\n'),
    c('PLAN8-redefined', 'PLAN 8', 'sub f() { return 1 } sub f() { return 2 } say f();', out='2\n', err='Subroutine f redefined'),
    c('PLAN8-undefined', 'PLAN 8', 'say "before"; g(1); say "after";', out='before\n', err='Undefined subroutine &main::g called', exit=255),
