    c('T5-more', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my $k = 0; for my $x (@a) { push @a, $x + 10 if $k++ < 2; print $x, " "; } say scalar(@a); @a = (1,2,3,4); for my $x (@a) { shift @a; print $x, " "; } say ""; @a = (1,2,3); for my $x (@a) { @a = (7,8,9) if $x == 1; print $x, " "; } say "";', out='1 2 3 11 12 5\n1 3 \n1 8 9 \n'),
    c('T5-reach', 'TRAPS; PLAN 9', 'my @a = (1,2); my @b = (3,4); for my $x (@a, @b) { $b[0] = 9; print $x; } say ""; for my $x (@a[0,1]) { $a[1] = 7; print $x; } say ""; my $c = 1; for my $x ($c ? @a : @b) { $a[1] = 5; print $x } say ""; for my $x ($a[0], $a[1]) { $a[1] = 6; print $x } say ""; for my $x (@a, ()) { $a[0] = 8; print $x } say "";', out='1294\n17\n15\n16\n86\n'),
    c('T5-sub', 'TRAPS; PLAN 9', 'my @a = (1,2,3); sub poke() { $a[2] = 30; return 0; } for my $x (@a) { poke(); print $x, " " } say "";', out='1 2 30 \n'),
    c('T5-range', 'TRAPS; PLAN 9', 'my $n = 3; for my $i (1..$n) { $n = 10; print $i; } say ""; my @a = (1,2,3); for my $i (0..$#a) { push @a, 0 if $i == 0; print $i; } say ""; for my $i (1.5..3.5) { print $i } say ""; for my $i (3..1) { print $i } say "none"; for my $i (1..3) { $i++; print $i } say "";', out='123\n012\n123\nnone\n234\n'),
    c('T5-alias', 'TRAPS; PLAN 9', 'my @a = (1,2,3); for my $x (@a) { $x *= 2; } say $a[0], $a[1], $a[2];', out='246\n'),
    c('T13-more', 'TRAPS; PLAN 9', 'my ($p,$q)=(1,2); for my $x ($p,$q) { $p = 7; print $x } say ""; for my $x ($p + 0, $q) { $q = 9; print $x } say "";', out='72\n79\n'),
    c('T14-more', 'TRAPS; PLAN 9', 'my $x = 10; for $x (1,2) { print $x } say $x; for (1,2) { print "x" } say "";', out='1210\nxx\n'),
    c('T149', 'TRAPS; PLAN 9', 'my @a = (1,2,3); say $a[0] + ($a[0] = 10) + $a[0]; @a = (1,2,3); say $a[0] + shift(@a); @a = (1,2,3); say $a[0] . "-" . shift(@a); @a = (1,2,3); say $a[2] + pop(@a); @a = (1,2,3); sub chg() { $a[0] = 50; return 1 } say $a[0] + chg(); @a = (1,2,3); say $a[1] * splice(@a, 0, 1);', out='30\n2\n1-1\n6\n51\n2\n'),
    c('T149-freed', 'TRAPS; PLAN 9', 'my @a = (1,2,3); say $a[0] + (@a = (7,8))[0];', out='7\n', err='Use of uninitialized value in addition'),
