    c('T149-args', 'TRAPS; PLAN 9', 'my @a = (1,2); sub bump() { $a[1] = 9; return 5 } sub f($x //= bump(), $y = 0) { return "$x,$y" } say f(undef, $a[1]); @a = (undef, 2); say f(@a); @a = (1,2,3); sub two($p, $q) { return "$p|$q" } say two($a[0], shift(@a)); @a = (1,2,3); sub chg() { $a[0] = 50; return 1 } say two($a[0], chg());', out='5,9\n5,9\n1|1\n50|1\n'),
    c('T150', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @e; my @f = @a || (9); say scalar(@f), $f[0]; my @d = @e || (1,2); say scalar(@d); my $v = @e || 7; say $v; say @a && "t";', out='13\n2\n7\nt\n'),
    c('T151', 'TRAPS; PLAN 9', 'my @a = (4,5,6); my $x = @a[0,1]; say $x; my $e = (@a); say $e; my ($y) = (4,5,6); say $y; my $c = () = (4,5,6); say $c; my $n = (my ($p, $q) = @a); say $n; my $s = splice(@a, 0, 2); say $s;', out='5\n3\n4\n3\n3\n5\n'),
