    c('PLAN9-assign', 'PLAN 9', 'my ($p, $q) = (1, 2); ($p, $q) = ($q, $p); say "$p $q"; my ($x, $y, $z) = (1, 2); say defined($z) ? "d" : "u"; my ($m, $n) = (1,2,3); say "$m $n"; my ($f, @rest) = (1,2,3); say $f, scalar(@rest); my (undef, $s) = (1, 2); say $s; my @c = (1, (2, 3), ((4))); say scalar(@c); my @d = 5; say scalar(@d); my @t = (1,2,3,); say scalar(@t); ($x, $y) = ($y, $x + $y); say "$x $y";', out='2 1\nu\n1 2\n12\n2\n4\n1\n3\n2 3\n'),
