    c('PLAN9-push', 'PLAN 9', 'my @a; my $r = push @a, 1, 2; say $r; say pop(@a); say shift(@a); my $u = pop(@a); say defined($u) ? "d" : "u"; $r = unshift @a, 5, 6; say $r, $a[0], $a[1]; my @b = (7, 8); push @a, @b, 9; say scalar(@a); push @a, @a; say scalar(@a);', out='2\n2\n1\nu\n256\n5\n10\n'),
    c('PLAN9-push-none', 'PLAN 9', 'my @a; push @a; say scalar(@a);', out='0\n', err='Useless use of push with no values'),
    c('PLAN9-splice', 'PLAN 9', 'my @a = (0,1,2,3,4,5); my @r = splice(@a, 1, 2); say "@r | @a"; @r = splice(@a, 2); say "@r | @a"; @r = splice(@a, 1, 0, 7, 8); say "@r | @a"; @r = splice(@a, -1); say "@r | @a"; @r = splice(@a, 0, -1); say "@r | @a"; @r = splice(@a); say "@r | @a"; @a = (1,2,3); @r = splice(@a, 3, 1, 9); say "@a"; @r = splice(@a, 1, 10); say "@r | @a";', out='1 2 | 0 3 4 5\n4 5 | 0 3\n | 0 7 8 3\n3 | 0 7 8\n0 7 | 8\n8 | \n1 2 3 9\n2 3 9 | 1\n'),
    c('PLAN9-splice-past', 'PLAN 9', 'my @a = (1,2,3); my @r = splice(@a, 5, 1); say scalar(@a);', out='3\n', err='splice\\(\\) offset past end of array'),
    c('PLAN9-splice-before', 'PLAN 9', 'my @a = (1,2,3); my @r = splice(@a, -9);', err='Modification of non-creatable array value attempted, subscript -9', exit=255),
    c('PLAN9-range', 'PLAN 9', 'my @a = (1..5); say scalar(@a); @a = (3..1); say scalar(@a); @a = (-2..2); say "@a"; @a = (1.9..4.1); say "@a"; my $n = 3; @a = (1..$n); say "@a"; @a = (9223372036854775806..9223372036854775807); say scalar(@a);', out='5\n0\n-2 -1 0 1 2\n1 2 3 4\n1 2 3\n2\n'),
    c('PLAN9-range-far', 'PLAN 9', 'my @a = (1e20..1e20);', err='Range iterator outside integer range', exit=255),
    c('PLAN9-foreach', 'PLAN 9', 'my @a = (1,2,3); for my $x (@a) { print $x; } say ""; foreach my $x (@a, 4, 5..6) { print $x; } say ""; OUT: for my $x (@a) { for my $y (@a) { next OUT if $y > $x; last OUT if $x == 3; print $x, $y, " "; } } say ""; my $x = 5; for my $x (1..$x) { print $x } say $x; my @u = (1); $u[2] = 3; for my $e (@u) { print defined($e) ? $e : "u" } say "";', out='123\n123456\n11 21 22 \n123455\n1u3\n'),
    c('PLAN9-foreach-many', 'PLAN 9', 'my $c = 0; for my $i (1..3000000) { $c++ } say $c;', out='3000000\n'),
    c('PLAN9-flatten', 'PLAN 9', 'sub three($p, $q, $r) { return "$p$q$r" } my @a = (1,2); say three(@a, 3); say three(0, @a); my @e; say three(@e, 1, @a); sub cnt($p = "-", $q = "-") { return "$p$q" } say cnt(@e); say cnt(@a); say cnt((@a)[0]);', out='123\n012\n112\n--\n12\n1-\n'),
    c('PLAN9-flatten-many', 'PLAN 9', 'sub two($p, $q) { return "$p$q" } my @a = (1,2,3); say "x"; say two(@a);', out='x\n', err="Too many arguments for subroutine 'main::two' \\(got 3; expected 2\\)", exit=255),
    c('PLAN9-nothing', 'PLAN 9', 'sub f() { return 5 } sub none() { return } my @a = f(); say scalar(@a); my @c = none(); say scalar(@c); my @d = (1, none(), 2); say scalar(@d); my ($y, $z) = (none(), 7); say $y;', out='1\n0\n2\n7\n'),
    c('PLAN9-slice', 'PLAN 9', 'my @a = (10,20,30,40); my @s = @a[1,2]; say "@s"; @s = @a[1..3]; say "@s"; @s = @a[-1,0]; say "@s"; @s = @a[5,1]; say defined($s[0]) ? "d" : "u", $s[1]; my @i = (0,2); @s = @a[@i]; say "@s"; my ($x, $y) = @a[2,3]; say "$x$y"; say((10,20,30)[1]); my @t = (10,20,30)[0,2]; say "@t"; my @e = (@a)[9,10]; say scalar(@e); @e = ()[0,1]; say scalar(@e);', out='20 30\n20 30 40\n40 10\nu20\n10 30\n3040\n20\n10 30\n2\n0\n'),
    c('PLAN9-slice-left', 'PLAN 9', 'my @a = (1,2,3); @a[0,1] = (8,9); say "@a"; $#a = 0; say scalar(@a);', out='8 9 3\n1\n'),
    c('PLAN9-repeat', 'PLAN 9', 'my @a = (0) x 3; say "@a"; @a = (1,2) x 2; say "@a"; my @b = (@a) x 2; say scalar(@b); @a = ("a") x 0; say scalar(@a); @a = "ab" x 2; say "@a";', out='0 0 0\n1 2 1 2\n8\n0\nabab\n'),
    c('PLAN9-names', 'PLAN 9', 'my @a = (1,2); my @b = (3); say $a[0] + $b[0]; my $x = 9; my @x = (1,2,3); say $x; say $x[0]; say scalar(@x);', out='4\n9\n1\n3\n'),
    c('PLAN9-element-ops', 'PLAN 9', 'my @a = (1,2,3); $a[0]++; ++$a[1]; $a[2] += 10; $a[0] .= "x"; $a[5] //= 7; $a[4]++; say $a[0], $a[1], $a[2], $a[4], $a[5]; my @u; $u[2] .= "s"; $u[1] += 5; $u[0]++; say "@u"; my $i = 0; $a[$i++] = $i; say $a[0]; $a[$i] = $i++; say $a[2], $i; my @t = (10,20,30); $i = 0; say $t[$i++] + $t[$i++];', out='2x31317\n1 5 s\n1\n12\n30\n'),
    c('PLAN9-undef', 'PLAN 9', 'my @a = (1); @a = undef; say scalar(@a); my @b = (undef, undef); say scalar(@b); @a = (); say scalar(@a);', out='1\n2\n0\n'),
    c('PLAN9-scalar', 'PLAN 9', 'my @a = (1,2,3); say scalar(@a); say scalar(@a) + 1; say scalar(1 + 1);', out='3\n4\n2\n'),
    c('PLAN9-later', 'PLAN 9', 'my @a = (1,2,3); say exists $a[1] ? "y" : "n"; delete $a[2]; say scalar(@a); my @r = (1,2); for my ($i, $j) (@a, 4, 5) { print "$i$j " } say "";', out='y\n2\n12 45 \n'),
    # ---- found by the review of step 9
    c('T157', 'TRAPS; PLAN 9', 'my $x = 1; sub bump() { $x = 9; return 5 } my @b = ($x, bump()); say "@b"; $x = 1; say $x, bump(); $x = 1; my ($p, $q) = ($x, bump()); say "$p $q"; my $i = 1; @b = ($i, $i++); say "@b"; @b = ($i, $i = 7); say "@b"; $x = 1; @b = (($x) x 2, bump()); say "@b"; $x = 1; @b = ((1 ? $x : 0), bump()); say "@b";', out='9 5\n95\n9 5\n2 1\n7 7\n9 9 5\n9 5\n'),
    c('T157-array', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); sub chg() { $a[0] = 50; return 5 } my @b = (@a, chg()); say "@b"; @a = (1, 2, 3); say @a, chg(); @a = (1, 2, 3); @b = (@a[0, 1], chg()); say "@b"; @a = (1, 2, 3); @b = ($a[0], chg()); say "@b"; @a = (1, 2, 3); for my $x (@a, chg()) { print $x, " "; } say "";', out='50 2 3 5\n50235\n50 2 5\n50 5\n50 2 3 5 \n'),
    c('T158', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); my $i = 0; $a[$i] = ($i = 2); say "@a"; @a = (1, 2, 3); sub bump() { $a[0] = 99; return 1 } $a[bump()] = $a[0]; say "@a"; @a = (1, 2, 3); $i = 0; ($i, $a[$i]) = (1, 5); say "@a $i";', out='1 2 2\n99 99 3\n5 2 3 1\n'),
    c('T159', 'TRAPS; PLAN 9', 'my @a = (1, 2, 3); my $i = 0; $a[$i] += ($i = 2); say "@a"; @a = (1, 2, 3); $a[0] += shift(@a); say "@a"; @a = (1, 2, 3); $a[$#a] += pop(@a); say "@a"; my @e; $e[5] //= push(@e, 1); say scalar(@e), $e[5];', out='3 2 3\n2 3\n1 2\n77\n'),
    c('T160', 'TRAPS; PLAN 9', 'my @a; $a[5] &&= 1; say scalar(@a);', out='6\n'),
    c('T160-before', 'TRAPS; PLAN 9', 'my @e; say "a"; $e[-1] &&= 5; say "after";', out='a\n', err='Modification of non-creatable array value attempted, subscript -1', exit=255),
    c('T160-order', 'TRAPS; PLAN 9', 'my @a = (1); sub p($v) { say $v; return $v } $a[-9] += p(5);', out='', err='Modification of non-creatable array value attempted, subscript -9', exit=255),
    c('T161', 'TRAPS; PLAN 9', 'sub f($x = 0, $y = 0) { return 1 } my @a; for my $x ($a[5]) { say scalar(@a); } my @b; for my $x (@b[5, 6]) { } say scalar(@b); my @c; f($c[5]); say scalar(@c); f(@c[5, 6]); say scalar(@c); my @d; my $r = $d[5] // 0; my @t = @d[5, 6]; say scalar(@d), " ", scalar(@t);', out='6\n7\n0\n7\n0 2\n'),
    c('T161-before', 'TRAPS; PLAN 9', 'my @a; for my $x ($a[-5]) { say "in"; } say "after";', out='', err='Modification of non-creatable array value attempted, subscript -5', exit=255),
    c('T162', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @b = (4); for my $x ((@a) x 2) { $a[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x ((@a)[0, 1]) { $a[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x (@a && @b) { $b[0] = 9; print $x; } say ""; @a = (1,2,3); for my $x ($#a) { push @a, 7; print $x; } say ""; my $s = "abc"; for my $x (substr($s, 0, 1)) { $s = "zzz"; print $x; } say "";', out='923923\n92\n9\n3\nz\n'),
    c('T162-or', 'TRAPS; PLAN 9', 'my @a = (1,2,3); my @b = (4); for my $x (@a || @b) { print $x, " "; } say "";', out='3 \n'),
    c('T163', 'TRAPS; PLAN 9', 'sub p($v) { print "<", $v, ">"; return $v } say((p(10), p(20))[p(1)]); my $i = 0; say(($i, 5)[$i++]); my @a = (1, 2, 3); sub sh() { shift(@a); return 0 } say((@a)[sh()]);', out='<1><10><20>20\n1\n2\n'),
    c('T164', 'TRAPS; PLAN 9', 'my @e; my @b = (@e)[0, 1]; say scalar(@b); @b = (@e)[0]; say scalar(@b); @b = (1, 2, 3)[5, 6]; say scalar(@b); @b = (1, 2, 3)[5]; say scalar(@b); sub f($x = "d", $y = "d") { return $x . $y } say f((@e)[0]); my $v = (@e)[0]; say defined($v) ? 1 : 0;', out='0\n0\n2\n1\ndd\n0\n'),
    c('T165', 'TRAPS; PLAN 9', 'my @a = (1,2,3,4,5); my @r = splice(@a, 0, 1e30); say scalar(@r), " ", scalar(@a); @a = (1,2,3,4,5); @r = splice(@a, 1e30); say scalar(@r), " ", scalar(@a);', out='4 1\n1 4\n'),
    c('T166', 'TRAPS; PLAN 9', 'my $lo = -9223372036854775807 - 1; my @r = ($lo .. $lo + 1); say scalar(@r); for my $i (0, $lo .. $lo + 1) { print "."; } say ""; for my $i ($lo .. $lo + 1) { print "."; } say "not reached";', out='2\n...\n', err='Range iterator outside integer range', exit=255),
    c('T166-edge', 'TRAPS; PLAN 9', 'my $n = 0; for my $i (-9223372036854775295 .. -9223372036854775294) { $n++; } say $n; for my $i (3 .. -9223372036854775295) { $n++; } say $n; for my $i (3 .. -9223372036854775296) { $n++; } say "not reached";', out='2\n2\n', err='Range iterator outside integer range', exit=255),
    c('T169', 'TRAPS; PLAN 9', 'my @a = (1); for my $x (1 ? $a[5] : 0) { } print scalar(@a); my @b = (1); for my $x (0 || $b[5], 1 && $b[7]) { } print " ", scalar(@b); my @c = (1); for my $x (($c[5]) x 2, +$c[6]) { } print " ", scalar(@c); my @d = (1); for my $x ($d[5] || 0, $d[5] // 1, $d[5] ? 1 : 2, ($d[5], 1)[0]) { } say " ", scalar(@d);', out='6 8 7 1\n'),
    c('T170', 'TRAPS; PLAN 9', 'my @a = (1, 2); for my $x (@a) { my $x = 5; print $x; } say "";', out='55\n'),
    c('T171', 'TRAPS; PLAN 9', 'my $x = 7; for $x (1, 2) { print $x; } say $x; foreach (my $k = 0; $k < 2; $k++) { print $k; } say "";', out='127\n01\n'),
    c('T172', 'TRAPS; PLAN 9', 'my $n = 3; for my $i (1 .. $n) { $n = 1; print $i; } say "";', out='123\n'),
    c('T166-high', 'TRAPS; PLAN 9', 'my $n = 0; for my $i (9223372036854775805 .. 9223372036854775807) { $n++; } say $n;', out='3\n'),
    # ---- step 10, proposing it
    c('T173', 'TRAPS; PLAN 10', 'for my $r (2147483647, 2147483648, 4294967296, 4294967297, -2147483648, -2147483649, 1.9, -1.9, -0.5) { my @s = sort { $r } (1, 2); print "$r:@s  "; } say "";', out='2147483647:2 1  2147483648:1 2  4294967296:1 2  4294967297:2 1  -2147483648:1 2  -2147483649:2 1  1.9:2 1  -1.9:1 2  -0.5:1 2  \n'),
    c('T173-log', 'TRAPS; PLAN 10', 'my @log; my @s = sort { push @log, "$a$b"; $a <=> $b } (5,3,8,1,9,2,7); say "@log"; @log = (); @s = sort { push @log, "$a$b"; $b <=> $a } (5,3,8,1,9,2,7); say "@log"; @log = (); @s = reverse sort { push @log, "$a$b"; $a <=> $b } (5,3,8,1,9,2,7); say "@log | @s";', out='53 81 92 31 38 58 27 79 12 23 37 75 78 89\n53 81 92 58 51 31 97 72 89 87 57 52 32 21\n53 81 92 31 38 58 27 79 12 23 37 75 78 89 | 9 8 7 5 3 2 1\n'),
    c('T173-runs', 'TRAPS; PLAN 10', 'my @log; my @s = sort { push @log, "$a$b"; $a <=> $b } (1,2,3,4,5,6,7); say "@log"; @log = (); @s = sort { push @log, "$a$b"; $a <=> $b } (7,6,5,4,3,2,1); say "@log";', out='12 34 56 13 32 57 76 15 52 53 54\n76 54 32 64 65 21 41 42 43\n'),
    c('T173-loose', 'TRAPS; PLAN 10', 'my @s = sort { 1 } (1,2,3,4,5); say "@s"; @s = sort { -1 } (1,2,3,4,5); say "@s"; @s = sort { $a <=> $b } (9007199254740993, 9007199254740992.0, 9007199254740992); say "@s";', out='5 4 3 2 1\n1 5 3 2 4\n9007199254740992 9007199254740993 9.00719925474099e+15\n'),
    c('T173-stable', 'TRAPS; PLAN 10', 'my @s = reverse sort { lc($a) cmp lc($b) } ("b", "A", "a", "B"); say "@s"; @s = sort { lc($b) cmp lc($a) } ("b", "A", "a", "B"); say "@s"; @s = sort (10, 9, 2.5, "3", true, 1e1, "a", "B"); say "@s";', out='B b a A\nb B A a\n1 10 10 2.5 3 9 B a\n'),
    c('T174', 'TRAPS; PLAN 10', 'sub f() { my @s = sort { return 5 } (3,1,2); return "@s"; } say f(); sub g() { my @s = map { return 5 } (3,1,2); return "@s"; } say g(); my @t = sort { return $a <=> $b } (3,1,2); say "@t";', out='2 1 3\n5\n1 2 3\n'),
    c('T175', 'TRAPS; PLAN 10', 'my @s = map { "a", $_ } (1,2);', compiles=False, err='syntax error'),
    c('T175-number', 'TRAPS; PLAN 10', 'my @s = map { 1, $_ } (1,2);', compiles=False, err='syntax error'),
    c('T175-empty', 'TRAPS; PLAN 10', 'my @s = map { } (1,2);', compiles=False, err='syntax error'),
    c('T175-grep', 'TRAPS; PLAN 10', 'my @s = grep { 1, 0 } (1,2);', compiles=False, err='syntax error'),
    c('T175-sort', 'TRAPS; PLAN 10', 'my @s = sort { 1, 0 } (1,2);', compiles=False, err='syntax error'),
    c('T175-blocks', 'TRAPS; PLAN 10', 'my @s = map { 1.5, $_ } (1,2); print scalar(@s); @s = map { -1, $_ } (1,2); print scalar(@s); @s = map { true, $_ } (1,2); print scalar(@s); @s = map { lc("A"), $_ } (1,2); print scalar(@s); @s = map { $_, 1 } (1,2); print scalar(@s); @s = map { ; 1, $_ } (1,2); print scalar(@s); @s = map {; } (1,2); say scalar(@s);', out='4444440\n'),
    c('T176', 'TRAPS; PLAN 10', 'my @s = map { if ($_ > 1) { $_ } } (1,2,3); say scalar(@s), ":", join(",", @s);', out='3:,2,3\n'),
    c('T176-grep', 'TRAPS; PLAN 10', 'my @s = grep { ($_, 0) } (1,2,3); say scalar(@s);', out='0\n', err='Useless use of a variable in void context'),
    c('T177', 'TRAPS; PLAN 10', 'my @a = (1); my @r = map { $_ } $a[5]; print scalar(@a); @r = grep { 1 } $a[7]; print " ", scalar(@a); @r = map { $_ } @a[9, 10]; say " ", scalar(@a);', out='6 8 11\n'),
    c('T177-not', 'TRAPS; PLAN 10', 'my @a = (1); my $j = join(",", $a[9] // 0); my @r = reverse($a[12] // 0, 1); say scalar(@a);', out='1\n'),
    c('T177-sort', 'TRAPS; PLAN 10', 'my @a = (1); my @r = sort { $a <=> $b } $a[9], 1; say scalar(@a);', out='1\n', err='Use of uninitialized value in sort'),
    c('T178', 'TRAPS; PLAN 10', 'my @a = (1,2,3); my $n = grep { $_ > 1 } @a; my $m = map { ($_, $_) } @a; say "$n $m"; say "has" if grep { $_ == 2 } @a; say "n" . grep { $_ } @a; say 1 + map { $_ } @a;', out='2 6\nhas\nn3\n4\n'),
    c('T178-reverse', 'TRAPS; PLAN 10', 'my $r = reverse("abc", "def"); say $r; say reverse("abc", "def"); say scalar(reverse("abc"));', out='fedcba\ndefabc\ncba\n'),
    c('T178-sort', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my $s = sort { $a <=> $b } @a; say defined($s) ? $s : "undef";', out='undef\n', err='Useless use of sort in scalar context'),
    c('T179', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my @log; @a = sort { push @log, "$a[0]$a[1]$a[2]"; $a <=> $b } @a; say "@log | @a";', out='312 312 312 | 1 2 3\n'),
    c('T179-store', 'TRAPS; PLAN 10', 'my @a = (3,1,2); my @b = sort { $a[0] = 0; $a <=> $b } @a; say "@a | @b"; my @c = (3,1,2); my @d = sort { $a++; 0 } @c; say "@c";', out='0 1 2 | 0 1 2\n5 1 3\n'),
    c('T179-push', 'TRAPS; PLAN 10', 'my @a = (3,1,2); @a = sort { push @a, 1; $a <=> $b } @a; say "@a"; my @c = (3,1,2); my @d = sort { push @c, 1; $a <=> $b } @c; say "@c | @d";', out='1 2 3\n3 1 2 1 1 1 | 1 2 3\n'),
    c('T180', 'TRAPS; PLAN 10', 'sub show() { return $_ * 2 } my @s = map { show() } (1,2); say "@s"; sub cmpf() { return $a <=> $b } @s = sort { cmpf() } (3,1,2); say "@s";', out='2 4\n1 2 3\n'),
    c('T180-nest', 'TRAPS; PLAN 10', 'for (1,2) { print $_; for (7,8) { print $_; } print $_; } say ""; my @s = map { my $o = $_; map { $o . $_ } (1,2) } ("a","b"); say "@s"; @s = sort { my @t = sort { $b <=> $a } ($a, $b); $t[0] <=> $a } (3,1,2); say "@s";', out='17812782\na1 a2 b1 b2\n3 1 2\n'),
    c('T180-alias', 'TRAPS; PLAN 10', 'my @a = (1,2); for (@a) { $_ *= 2 } say "@a"; my @r = map { $_ *= 2 } @a; say "@a"; @r = grep { $_++ } @a; say "@a"; my $p = 1; my $q = 2; @r = map { $p = 7; $_ } ($p, $q); say "@r";', out='2 4\n4 8\n5 9\n7 2\n'),
    c('T180-default', 'TRAPS; PLAN 10', 'my @s = map { length } ("ab", "c"); say "@s"; @s = grep { defined } (1, undef); say scalar(@s); say for 1, 2;', out='2 1\n1\n1\n2\n'),
    c('T180-expr', 'TRAPS; PLAN 10', 'my @s = map lc, ("A", "B"); say "@s"; @s = grep $_ > 1, (1,2,3); say "@s"; @s = map +($_ * 2), (1,2); say "@s"; @s = (9, map { $_ * 2 } 1, 2, 9); say "@s";', out='a b\n2 3\n2 4\n9 2 4 18\n'),
    c('T180-expr-brackets', 'TRAPS; PLAN 10', 'my @s = map ($_ * 2), (1,2); say scalar(@s);', out='0\n', err='Useless use of a constant'),
    c('T181', 'TRAPS; PLAN 10', 'my @a = (1,2,3); my @r = map { push @a, 9 if @a < 6; $_ } @a; say "@r | @a"; for (@a) { push @a, 8 if @a < 8; print $_; } say "";', out='1 2 3 | 1 2 3 9 9 9\n12399988\n'),
    c('T182', 'TRAPS; PLAN 10', 'sub f(@rest, $x) { 1 }', compiles=False, err='Slurpy parameter not last'),
